inline QString u64text(std::uint64_t n){return QString::number(qulonglong(n));}
inline QJsonArray updateValues(std::uint64_t a=0,std::uint64_t b=0,std::uint64_t c=0){return {u64text(a),u64text(b),u64text(c)};}
