inline QJsonObject updateOperation(const Building& scene,const QString& kind,unsigned revision,const SceneOrigin* origin=nullptr){return {{"id","op-"+QUuid::createUuid().toString(QUuid::Id128)},{"revision",int(revision)},{"kind",kind},{"policy","conditional"},{"map",QString::fromStdString(scene.map_name)},{"sector",u64text(scene.sector_id)},{"selector",updateSelector(origin)},{"field",""},{"index",0},{"mask","0"},{"before",updateValues()},{"after",updateValues()},{"payload",""}};}
