inline std::uint64_t globalLocation(std::uint64_t local,std::uint64_t sector){return ((sector&0x3ffffff)*64+std::uint32_t(local))|(((sector>>26)*64+(local>>32))<<32);}
inline bool updateScalarAllowed(const std::string& field,unsigned type){return field=="DESCRIPTION" || field=="NAME" || field=="SOUND_EFFECT" || (type==16 && field=="CRITTER_DESCRIPTION_UNKNOWN") || (type==1 && (field=="PORTAL_LOCK_DIFFICULTY" || field=="PORTAL_KEY_ID")) || (type==2 && (field=="CONTAINER_LOCK_DIFFICULTY" || field=="CONTAINER_KEY_ID"));}
