inline QJsonObject updateHistory(const Building& scene){if(scene.update_history.empty())return {};auto doc=QJsonDocument::fromJson(QByteArray(reinterpret_cast<const char*>(scene.update_history.data()),int(scene.update_history.size())));if(!doc.isObject() || doc.object()["format"]!="worlded-update-history" || doc.object()["version"].toInt()!=1)throw std::runtime_error("Invalid published update history");return doc.object();}
