    auto scripts=[](const Sector& sector){std::vector<std::array<unsigned,4>> rows;for(auto script:sector.scripts())rows.push_back({script.tile,script.flags,script.counters,script.number});return rows;};if(scripts(scene.ground)!=scripts(beforeGround))result.unsupported<<"Tile or sector script attachments require an explicit migration.";
